export const simulateUnlock = async (req: Request, res: Response) => {
  try {
    const { reservationCode, pinCode } = req.body;

    // Tìm Reservation
    const reservation = await ReservationModel.findOne({ reservationCode });
    if (!reservation) {
      return res.status(404).json({ success: false, message: 'Invalid Reservation' });
    }

    // Giả lập check PIN (Ở hệ thống thật, PIN sẽ sinh và lưu vào DB)
    if (pinCode !== '1234') {
      const log = await AccessLogModel.create({
        reservationId: reservation._id,
        storageUnitId: reservation.storageUnitId!,
        customerId: reservation.customerId,
        action: AccessAction.UNLOCK_FAILED,
        accessMethod: AccessMethod.PIN_CODE,
        reason: 'Sai mã PIN giả lập'
      });
      return res.status(401).json({ success: false, message: 'Sai mã PIN', data: log });
    }

    // Kiểm tra trạng thái Hợp đồng
    if (reservation.status === ReservationStatus.OVERDUE) {
      const log = await AccessLogModel.create({
        reservationId: reservation._id,
        storageUnitId: reservation.storageUnitId!,
        customerId: reservation.customerId,
        action: AccessAction.DENIED_OVERDUE,
        accessMethod: AccessMethod.PIN_CODE,
        reason: 'Khóa do quá hạn thanh toán'
      });
      return res.status(403).json({ success: false, message: 'Kho bị khóa do quá hạn thanh toán.', data: log });
    }

    if (reservation.status !== ReservationStatus.ACTIVE) {
      return res.status(403).json({ success: false, message: 'Từ chối truy cập. Kho chưa được kích hoạt, đã trả kho, hoặc đang bị khóa.' });
    }

    // Mở khóa thành công
    const log = await AccessLogModel.create({
      reservationId: reservation._id,
      storageUnitId: reservation.storageUnitId!,
      customerId: reservation.customerId,
      action: AccessAction.UNLOCK_SUCCESS,
      accessMethod: AccessMethod.PIN_CODE,
      reason: 'Mở cửa thành công'
    });

    return res.json({ success: true, message: 'Mở cửa thành công!', data: log });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getMyAccessLogs = async (req: Request, res: Response) => {
  try {
    const logs = await AccessLogModel.find({ customerId: req.user!._id }).sort({ createdAt: -1 });
    return res.json({ success: true, data: logs });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getMyContracts = async (req: Request, res: Response) => {
  try {
    const contracts = await ContractModel.find({ customerId: req.user!._id })
      .populate('reservationId', 'reservationCode facilityId storageUnitId startDate endDate status')
      .sort({ createdAt: -1 });
    return res.json({ success: true, data: contracts });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getContractByReservationId = async (req: Request, res: Response) => {
  try {
    const reservationId = req.params.reservationId;
    const contract: any = await (ContractModel as any).findOne({ reservationId })
      .populate('reservationId', 'reservationCode facilityId storageUnitId startDate endDate status serviceType')
      .populate('customerId', 'fullName email phone');
    if (!contract) return res.status(404).json({ success: false, message: 'Contract not found for this reservation.' });

    const customerId = contract.customerId?._id ?? contract.customerId;
    const isOwner = customerId?.toString() === req.user!._id.toString();
    const isStaff = ['ADMIN', 'FACILITY_MANAGER', 'FACILITY_STAFF', 'BOM'].includes(req.user!.role);
    if (!isOwner && !isStaff) {
      return res.status(403).json({ success: false, message: 'Bạn không có đủ quyền truy cập!' });
    }
    return res.json({ success: true, data: contract });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getContractPrintData = async (req: Request, res: Response) => {
  try {
    const contract = await ContractModel.findById(req.params.id)
      .populate('reservationId')
      .populate('customerId', 'fullName email phone');
    if (!contract) return res.status(404).json({ success: false, message: 'Hợp đồng không tồn tại.' });
    return res.json({ success: true, data: contract });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getContractById = async (req: Request, res: Response) => {
  try {
    const contract = await ContractModel.findById(req.params.id)
      .populate('reservationId', 'reservationCode facilityId storageUnitId startDate endDate status serviceType');
    if (!contract) return res.status(404).json({ success: false, message: 'Contract not found' });

    // Check permission: FM, Admin, BOM or the owner
    const isOwner = contract.customerId.toString() === req.user!._id.toString();
    const isStaff = ['ADMIN', 'FACILITY_MANAGER', 'FACILITY_STAFF', 'BOM'].includes(req.user!.role);
    if (!isOwner && !isStaff) {
      return res.status(403).json({ success: false, message: 'Bạn không có đủ quyền truy cập!' });
    }
    if (['FACILITY_MANAGER', 'FACILITY_STAFF'].includes(req.user!.role)) {
      const reservation: any = contract.reservationId;
      if (!req.user!.assignedFacilityId || String(reservation?.facilityId?._id ?? reservation?.facilityId) !== req.user!.assignedFacilityId.toString()) {
        return res.status(404).json({ success: false, message: 'Contract not found' });
      }
    }

    return res.json({ success: true, data: contract });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const signContract = async (req: Request, res: Response) => {
  try {
    const contracts: any = ContractModel;
    const reservations: any = ReservationModel;
    const existing: any = await contracts.findOne({ _id: req.params.id, customerId: req.user!._id });
    if (existing) {
      const linkedReservation = await reservations.findById(existing.reservationId).select('serviceType facilityId bookingFlowVersion').exec();
      if (linkedReservation?.serviceType === FacilityServiceType.MANAGED_INVENTORY) {
        if (linkedReservation.bookingFlowVersion === 2) {
          const signed = await ManagedCheckinService.signContract(req.params.id, req.user! as any);
          return res.json({ success: true, data: signed });
        }
        const session = await mongoose.startSession();
        try {
          let signed: any = null;
          await session.withTransaction(async () => {
            const capacityLock = await ManagedFacilityCapacityModel.findOneAndUpdate(
              { facilityId: linkedReservation.facilityId }, { $inc: { bookingVersion: 1 } }, { new: true, session },
            ).exec();
            if (!capacityLock) return;
            const managedContract = await contracts.findOne({ _id: existing._id, customerId: req.user!._id, status: ContractStatus.DRAFT }).session(session).exec();
            if (!managedContract) return;
            const reservation = await reservations.findOne({ _id: managedContract.reservationId, customerId: req.user!._id, serviceType: FacilityServiceType.MANAGED_INVENTORY, status: ReservationStatus.CONTRACTED, expiresAt: { $gt: new Date() } }).session(session).exec();
            if (!reservation) return;
            managedContract.status = ContractStatus.SIGNED;
            managedContract.signedByCustomerAt = new Date();
            await managedContract.save({ session });
            await new ManagedReservationAuditModel({
              facilityId: reservation.facilityId, reservationId: reservation._id, actorId: req.user!._id,
              action: ManagedReservationAction.CONTRACT_SIGNED, fromStatus: ContractStatus.DRAFT, toStatus: ContractStatus.SIGNED,
            }).save({ session });
            signed = managedContract;
          }, { readConcern: { level: 'snapshot' }, writeConcern: { w: 'majority' } });
          if (!signed) return res.status(409).json({ success: false, message: 'Managed contract requires an active, held CONTRACTED reservation.' });
          return res.json({ success: true, data: signed });
        } finally { await session.endSession(); }
      }
    }
    const contract = await ContractModel.findOneAndUpdate(
      { _id: req.params.id, customerId: req.user!._id, status: ContractStatus.DRAFT } as any,
      { 
        status: ContractStatus.SIGNED, 
        signedByCustomerAt: new Date() 
      },
      { new: true }
    );
    if (!contract) return res.status(400).json({ success: false, message: 'Contract cannot be signed (not found or already signed).' });
    return res.json({ success: true, data: contract });
  } catch (error: any) {
    if (error instanceof ManagedCheckinError) return res.status(error.status).json({ success: false, message: error.message });
    return res.status(500).json({ success: false, message: error.message });
  }
};

/**
 * Staff xác nhận đơn đã ký giấy và tải ảnh chụp bằng chứng hợp đồng lên Cloudinary.
 * Cổng này mở khóa quyền thanh toán BALANCE (Đợt 2) cho Khách hàng.
 */

export const confirmSignedPaper = async (req: Request, res: Response) => {
  try {
    const contractId = req.params.id;
    const contract = await ContractModel.findById(contractId);
    if (!contract) {
      return res.status(404).json({ success: false, message: 'Hợp đồng không tồn tại.' });
    }

    const reservation = await ReservationModel.findById(contract.reservationId);
    if (!reservation) {
      return res.status(404).json({ success: false, message: 'Đơn đặt chỗ liên kết không tồn tại.' });
    }

    if (reservation.serviceType === FacilityServiceType.MANAGED_INVENTORY) {
      assertManagedProofFacilityScope(req.user!, reservation.facilityId);
      if (reservation.status === ReservationStatus.CHECKIN_READY && contract.status === ContractStatus.SIGNED &&
          contract.signedProofPublicId && contract.verifiedAt) {
        return res.json({ success: true, message: 'Signed-paper proof was already confirmed.', data: { contract, reservation } });
      }
      if (reservation.bookingFlowVersion === 2) {
        return res.status(409).json({ success: false,
          message: 'Version 2 Managed contracts must use the versioned digital-signature and balance flow.' });
      }
      if (reservation.activeClosureRequestId ||
          ![ReservationStatus.CONTRACTED, ReservationStatus.DEPOSIT_PAID].includes(reservation.status)) {
        return res.status(409).json({ success: false,
          message: 'Managed signed-paper confirmation requires an eligible pre-activation reservation with no pending closure.' });
      }
      if (!req.file) {
        return res.status(400).json({ success: false, message: 'Vui lòng tải lên ảnh chụp bằng chứng hợp đồng giấy đã ký.' });
      }

      // The external upload precedes MongoDB commit. If the transaction definitely aborts,
      // delete only this newly uploaded, unattached asset. Unknown commit outcomes are not deleted.
      const uploadResult = await CloudinaryService.uploadBuffer(req.file.buffer, 'wdp/signed-contracts');
      let transactionResult: { contract: any; reservation: any; replayed: boolean } | undefined;
      const session = await mongoose.startSession();
      try {
        await session.withTransaction(async () => {
          const current = await ReservationModel.findOne({ _id: reservation._id,
            serviceType: FacilityServiceType.MANAGED_INVENTORY }).session(session).exec();
          if (!current) throw new ContractControllerError(404, 'Đơn đặt chỗ liên kết không tồn tại.');
          assertManagedProofFacilityScope(req.user!, current.facilityId);
          if (current.bookingFlowVersion === 2) {
            throw new ContractControllerError(409, 'Version 2 Managed contracts must use the versioned digital-signature and balance flow.');
          }

          const currentContract = await ContractModel.findOne({ _id: contract._id, reservationId: current._id }).session(session).exec();
          if (!currentContract) throw new ContractControllerError(404, 'Hợp đồng không tồn tại.');
          if (current.status === ReservationStatus.CHECKIN_READY && currentContract.status === ContractStatus.SIGNED &&
              currentContract.signedProofPublicId && currentContract.verifiedAt) {
            transactionResult = { contract: currentContract, reservation: current, replayed: true };
            return;
          }
          if (current.activeClosureRequestId ||
              ![ReservationStatus.CONTRACTED, ReservationStatus.DEPOSIT_PAID].includes(current.status)) {
            throw new ContractControllerError(409,
              'Managed signed-paper confirmation requires an eligible pre-activation reservation with no pending closure.');
          }
          if (![ContractStatus.DRAFT, ContractStatus.SIGNED].includes(currentContract.status)) {
            throw new ContractControllerError(409, 'Contract is not eligible for signed-paper confirmation.');
          }

          const now = new Date();
          const updatedReservation = await ReservationModel.findOneAndUpdate({
            _id: current._id,
            serviceType: FacilityServiceType.MANAGED_INVENTORY,
            bookingFlowVersion: { $ne: 2 },
            status: { $in: [ReservationStatus.CONTRACTED, ReservationStatus.DEPOSIT_PAID] },
            activeClosureRequestId: null,
            $and: [transactionVersionFilter(current.inventoryVersion)],
          }, {
            $inc: { inventoryVersion: 1 },
            $set: { status: ReservationStatus.CHECKIN_READY },
            $push: { statusHistory: { status: ReservationStatus.CHECKIN_READY, actorId: req.user!._id,
              reason: 'Staff confirmed signed paper contract with proof image', createdAt: now } },
          }, { new: true, session, runValidators: true }).exec();
          if (!updatedReservation) throw new ContractControllerError(409,
            'Managed reservation changed or closure is pending; reload and retry.');

          currentContract.signedProofUrl = uploadResult.secureUrl;
          currentContract.signedProofPublicId = uploadResult.publicId;
          currentContract.signedProofUploadedAt = now;
          currentContract.verifiedByStaff = req.user!._id;
          currentContract.verifiedAt = now;
          if (req.body.paperContractNumber) currentContract.paperContractNumber = req.body.paperContractNumber;
          currentContract.status = ContractStatus.SIGNED;
          await currentContract.save({ session });
          await new ManagedReservationAuditModel({ facilityId: updatedReservation.facilityId,
            reservationId: updatedReservation._id, actorId: req.user!._id,
            action: ManagedReservationAction.CONTRACT_SIGNED,
            fromStatus: current.status, toStatus: ContractStatus.SIGNED,
            details: { contractId: currentContract._id, paperProofVerified: true,
              paperContractNumber: currentContract.paperContractNumber } }).save({ session });
          transactionResult = { contract: currentContract, reservation: updatedReservation, replayed: false };
        }, { readConcern: { level: 'snapshot' }, writeConcern: { w: 'majority' } });
      } catch (error: any) {
        const unknownCommit = error?.hasErrorLabel?.('UnknownTransactionCommitResult') ||
          error?.errorLabels?.includes?.('UnknownTransactionCommitResult');
        if (unknownCommit) {
          // Resolve only when both durable records point to this exact uploaded asset.
          const committedContract = await ContractModel.findOne({ _id: contract._id,
            reservationId: reservation._id, signedProofPublicId: uploadResult.publicId });
          const committedReservation = await ReservationModel.findOne({ _id: reservation._id,
            serviceType: FacilityServiceType.MANAGED_INVENTORY, status: ReservationStatus.CHECKIN_READY });
          if (committedContract && committedReservation) {
            return res.json({ success: true, message: 'Xác nhận hợp đồng giấy và tải ảnh bằng chứng lên Cloudinary thành công.',
              data: { contract: committedContract, reservation: committedReservation } });
          }
          throw new ContractControllerError(503, 'Contract confirmation outcome is uncertain; retry safely.');
        }
        try { await CloudinaryService.deleteAsset(uploadResult.publicId); } catch { /* best-effort cleanup of this unattached upload */ }
        if (error instanceof ContractControllerError) throw error;
        if (error?.code === 11000 || error?.code === 112 || error?.codeName === 'WriteConflict' ||
            error?.name === 'VersionError' || error?.hasErrorLabel?.('TransientTransactionError')) {
          throw new ContractControllerError(409, 'Managed reservation or contract changed concurrently; reload and retry.');
        }
        throw error;
      } finally {
        await session.endSession();
      }

      if (!transactionResult) throw new ContractControllerError(503, 'Contract confirmation outcome is uncertain; retry safely.');
      if (transactionResult.replayed) {
        try { await CloudinaryService.deleteAsset(uploadResult.publicId); } catch { /* best-effort cleanup of duplicate upload */ }
      }
      return res.json({ success: true,
        message: 'Xác nhận hợp đồng giấy và tải ảnh bằng chứng lên Cloudinary thành công.',
        data: { contract: transactionResult.contract, reservation: transactionResult.reservation } });
    }

    if (!req.file) {
      return res.status(400).json({ success: false, message: 'Vui lòng tải lên ảnh chụp bằng chứng hợp đồng giấy đã ký.' });
    }

    // Upload file ảnh lên Cloudinary folder wdp/signed-contracts
    const uploadResult = await CloudinaryService.uploadBuffer(req.file.buffer, 'wdp/signed-contracts');

    contract.signedProofUrl = uploadResult.secureUrl;
    contract.signedProofPublicId = uploadResult.publicId;
    contract.signedProofUploadedAt = new Date();
    contract.verifiedByStaff = req.user!._id;
    contract.verifiedAt = new Date();
    if (req.body.paperContractNumber) {
      contract.paperContractNumber = req.body.paperContractNumber;
    }
    contract.status = ContractStatus.SIGNED;
    await contract.save();

    // Cập nhật trạng thái đơn đặt chỗ sang CHECKIN_READY để mở quyền thanh toán Balance
    reservation.status = ReservationStatus.CHECKIN_READY;
    reservation.statusHistory.push({
      status: ReservationStatus.CHECKIN_READY,
      actorId: req.user!._id,
      reason: 'Staff confirmed signed paper contract with proof image',
      createdAt: new Date(),
    });
    await reservation.save();

    return res.json({
      success: true,
      message: 'Xác nhận hợp đồng giấy và tải ảnh bằng chứng lên Cloudinary thành công.',
      data: { contract, reservation },
    });
  } catch (error: any) {
    if (error instanceof ContractControllerError) {
      return res.status(error.status).json({ success: false, message: error.message });
    }
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getMyProfile = async (req: Request, res: Response) => {
  try {
    const userId = req.user!._id;
    let profile = await CustomerProfileModel.findOne({ userId }).populate('userId', 'email phone fullName').exec();
    if (!profile) {
      profile = await CustomerProfileModel.create({ userId });
    }
    return res.json({ success: true, data: profile });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const updateMyProfile = async (req: Request, res: Response) => {
  try {
    const userId = req.user!._id;
    const { identityCard, address, taxCode } = req.body;

    // SAFEGUARD: Khóa CCCD nếu đã có hợp đồng đang chạy
    if (identityCard) {
      const activeBookings = await ReservationModel.exists({
        customerId: userId,
        status: { $in: [ReservationStatus.CONTRACTED, ReservationStatus.PAID, ReservationStatus.ACTIVE] }
      });
      if (activeBookings) {
        return res.status(403).json({ success: false, message: 'Không thể cập nhật CCCD do bạn đang có hợp đồng hoạt động (Chống Race Condition).' });
      }
    }

    const profile = await CustomerProfileModel.findOneAndUpdate(
      { userId },
      { identityCard, address, taxCode, verificationStatus: VerificationStatus.PENDING },
      { new: true, upsert: true }
    ).populate('userId', 'email phone fullName');

    return res.json({ success: true, data: profile });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getCustomers = async (req: Request, res: Response) => {
  try {
    const profiles = await CustomerProfileModel.find().populate('userId', 'email phone fullName').exec();
    return res.json({ success: true, data: profiles });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getCustomerById = async (req: Request, res: Response) => {
  try {
    const profile = await CustomerProfileModel.findById(req.params.id).populate('userId', 'email phone fullName').exec();
    if (!profile) return res.status(404).json({ success: false, message: 'Không tìm thấy khách hàng.' });
    return res.json({ success: true, data: profile });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const verifyProfile = async (req: Request, res: Response) => {
  try {
    const { id } = req.params; // Profile ID
    const { status, note } = req.body; // VERIFIED or REJECTED

    const profile = await CustomerProfileModel.findByIdAndUpdate(
      id,
      { 
        verificationStatus: status, 
        verifiedBy: req.user!._id, 
        verifiedAt: new Date(),
        note 
      },
      { new: true }
    ).populate('userId', 'email phone fullName');

    if (!profile) return res.status(404).json({ success: false, message: 'Profile không tồn tại.' });

    return res.json({ success: true, data: profile });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getFacilities: RequestHandler = async (req, res, next) => {
  try { res.json({ success: true, ...await FacilityService.getFacilities(req.query, req.user) }); }
  catch (error) { next(error); }
};

export const getFacilityById: RequestHandler = async (req, res, next) => {
  try { res.json({ success: true, data: await FacilityService.getFacilityById(req.params.id) }); }
  catch (error) { next(error); }
};

export const deleteFacility: RequestHandler = async (req, res, next) => {
  try { res.json({ success: true, data: await FacilityService.deleteFacility(req.params.id, req.user) }); }
  catch (error) { next(error); }
};

export const restoreFacility: RequestHandler = async (req, res, next) => {
  try { res.json({ success: true, data: await FacilityService.restoreFacility(req.params.id, req.user) }); }
  catch (error) { next(error); }
};

export const createFacility: RequestHandler = async (req, res, next) => {
  try { 
    const result = await FacilityService.createFacility(req.body);
    const actor = req.user as any;
    AuditService.logAction({
      actorId: actor._id.toString(),
      actorRole: actor.role,
      action: ActionType.CREATE_FACILITY,
      entityType: 'Facility',
      entityId: (result as any)._id.toString(),
      after: result
    });
    res.status(201).json({ success: true, data: result }); 
  }
  catch (error) { next(error); }
};

export const updateFacility: RequestHandler = async (req, res, next) => {
  try { 
    const result = await FacilityService.updateFacility(req.params.id, req.body);
    const actor = req.user as any;
    AuditService.logAction({
      actorId: actor._id.toString(),
      actorRole: actor.role,
      action: ActionType.UPDATE_FACILITY,
      entityType: 'Facility',
      entityId: req.params.id as string,
      after: req.body // Log payload body
    });
    res.json({ success: true, data: result }); 
  }
  catch (error) { next(error); }
};

export const updateFacilityStatus: RequestHandler = async (req, res, next) => {
  try { 
    const result = await FacilityService.updateFacilityStatus(req.params.id, req.body);
    const actor = req.user as any;
    AuditService.logAction({
      actorId: actor._id.toString(),
      actorRole: actor.role,
      action: ActionType.UPDATE_FACILITY_STATUS,
      entityType: 'Facility',
      entityId: req.params.id as string,
      after: { status: req.body.status }
    });
    res.json({ success: true, data: result }); 
  }
  catch (error) { next(error); }
};

export const createInspection = async (req: Request, res: Response) => {
  try {
    const inspection = new InspectionModel({
      ...req.body,
      inspectedBy: req.user!._id
    });
    await inspection.save();
    return res.status(201).json({ success: true, data: inspection });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const getInspections = async (req: Request, res: Response) => {
  try {
    const filter: any = {};
    if (req.query.reservationId) filter.reservationId = req.query.reservationId;
    if (req.query.storageUnitId) filter.storageUnitId = req.query.storageUnitId;

    const inspections = await InspectionModel.find(filter)
      .populate('reservationId', 'reservationCode customerId startDate endDate status')
      .populate('facilityId', 'name')
      .populate('storageUnitId', 'unitCode')
      .populate('inspectedBy', 'fullName email')
      .sort({ createdAt: -1 });
    return res.json({ success: true, data: inspections });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

export const completeInspection = async (req: Request, res: Response) => {
  try {
    const before = await InspectionModel.findById(req.params.id);
    if (!before) return res.status(404).json({ success: false, message: 'Inspection not found or already completed' });

    if (before.type === InspectionType.CHECK_IN) {
      if (process.env.NODE_ENV !== 'development' && process.env.NODE_ENV !== 'test') {
        return res.status(404).json({ success: false, message: 'Self-Storage CHECK_IN activation is disabled in this environment pending payment verification.' });
      }
      if (before.status !== InspectionStatus.DRAFT) {
        return res.status(409).json({ success: false, message: 'Inspection is already completed.' });
      }

      const linkedReservation = await ReservationModel.findById(before.reservationId).exec();
      if (linkedReservation?.serviceType === FacilityServiceType.MANAGED_INVENTORY) {
        return res.status(409).json({ success: false, message: 'Managed Inventory quota activation does not use Self Storage inspections.' });
      }
      if (!linkedReservation || linkedReservation.serviceType !== FacilityServiceType.SELF_STORAGE ||
          linkedReservation.status !== ReservationStatus.PAID) {
        return res.status(409).json({ success: false, message: 'CHECK_IN activation requires a PAID Self-Storage Reservation.' });
      }
      const reservationFacilityId = String(linkedReservation.facilityId).toLowerCase();
      if (!req.user?.assignedFacilityId || String(req.user.assignedFacilityId).toLowerCase() !== reservationFacilityId ||
          String(before.facilityId).toLowerCase() !== reservationFacilityId ||
          !linkedReservation.storageUnitId || String(before.storageUnitId).toLowerCase() !== String(linkedReservation.storageUnitId).toLowerCase()) {
        return res.status(404).json({ success: false, message: 'Inspection or Reservation not found.' });
      }
      const storageUnit = await StorageUnitModel.findOne({
        _id: before.storageUnitId,
        facilityId: linkedReservation.facilityId,
        deletedAt: { $exists: false },
      }).exec();
      if (!storageUnit) {
        return res.status(409).json({ success: false, message: 'Inspection, Reservation and StorageUnit linkage is invalid.' });
      }

      const session = await mongoose.startSession();
      let completedInspection: any = null;
      let transactionError: any = null;
      try {
        await session.withTransaction(async () => {
          completedInspection = null;
          // Match Self-Storage booking: serialize on StorageUnit before touching Inspection or Reservation.
          const storageUnitWriter: any = StorageUnitModel;
          const inspectionWriter: any = InspectionModel;
          const reservationWriter: any = ReservationModel;
          const lockedUnit = await storageUnitWriter.findOneAndUpdate({
            _id: before.storageUnitId,
            facilityId: before.facilityId,
            deletedAt: { $exists: false },
            ...versionCas(storageUnit.bookingVersion, 'bookingVersion'),
          }, { $inc: { bookingVersion: 1 } },
          { new: true, session }).exec();
          if (!lockedUnit) throw new InspectionActivationError(409, 'StorageUnit changed before CHECK_IN activation.');

          const activated = await reservationWriter.findOneAndUpdate({
            _id: linkedReservation._id,
            serviceType: FacilityServiceType.SELF_STORAGE,
            status: ReservationStatus.PAID,
            facilityId: linkedReservation.facilityId,
            storageUnitId: linkedReservation.storageUnitId,
            ...versionCas(linkedReservation.__v, '__v'),
          }, { $set: { status: ReservationStatus.ACTIVE },
            $inc: { __v: 1 },
            $push: { statusHistory: { status: ReservationStatus.ACTIVE, actorId: req.user!._id,
              reason: 'Hoàn tất bàn giao kho (CHECK_IN)', createdAt: new Date() } } },
          { new: true, session }).exec();
          if (!activated) throw new InspectionActivationError(409, 'Reservation changed before CHECK_IN activation.');

          completedInspection = await inspectionWriter.findOneAndUpdate({
            _id: before._id,
            status: InspectionStatus.DRAFT,
            type: InspectionType.CHECK_IN,
            reservationId: linkedReservation._id,
            facilityId: linkedReservation.facilityId,
            storageUnitId: linkedReservation.storageUnitId,
            ...versionCas(before.__v, '__v'),
          }, { $set: { status: InspectionStatus.COMPLETED }, $inc: { __v: 1 } }, { new: true, session }).exec();
          if (!completedInspection) throw new InspectionActivationError(409, 'Inspection changed before CHECK_IN activation.');

          const occupiedUnit = await storageUnitWriter.findOneAndUpdate({
            _id: before.storageUnitId,
            facilityId: before.facilityId,
            deletedAt: { $exists: false },
            bookingVersion: currentVersion(storageUnit.bookingVersion) + 1,
          }, { $set: { status: StorageUnitStatus.OCCUPIED } }, { new: true, session }).exec();
          if (!occupiedUnit) throw new InspectionActivationError(409, 'StorageUnit changed before CHECK_IN could be committed.');
        }, { readConcern: { level: 'snapshot' }, writeConcern: { w: 'majority' } });
      } catch (error: any) {
        transactionError = error;
      } finally {
        await session.endSession();
      }

      if (transactionError) {
        if (hasTransactionErrorLabel(transactionError, 'UnknownTransactionCommitResult')) {
          try {
            const inspectionReader: any = InspectionModel;
            const reservationReader: any = ReservationModel;
            const durableInspection = await inspectionReader.findOne({
              _id: before._id, type: InspectionType.CHECK_IN, status: InspectionStatus.COMPLETED,
              reservationId: linkedReservation._id, facilityId: linkedReservation.facilityId,
              storageUnitId: linkedReservation.storageUnitId,
            }).exec();
            const durableReservation = await reservationReader.findOne({
              _id: linkedReservation._id, serviceType: FacilityServiceType.SELF_STORAGE,
              status: ReservationStatus.ACTIVE, facilityId: linkedReservation.facilityId,
              storageUnitId: linkedReservation.storageUnitId,
              statusHistory: { $elemMatch: { status: ReservationStatus.ACTIVE, actorId: req.user!._id,
                reason: 'Hoàn tất bàn giao kho (CHECK_IN)' } },
            }).exec();
            const durableUnit = await StorageUnitModel.findOne({
              _id: linkedReservation.storageUnitId, facilityId: linkedReservation.facilityId,
              deletedAt: { $exists: false }, status: StorageUnitStatus.OCCUPIED,
            }).exec();
            if (durableInspection && durableReservation && durableUnit) completedInspection = durableInspection;
            else return res.status(503).json({ success: false, message: 'CHECK_IN outcome is uncertain; verify state before retrying.' });
          } catch {
            return res.status(503).json({ success: false, message: 'CHECK_IN outcome is uncertain; verify state before retrying.' });
          }
        } else if (transactionError instanceof InspectionActivationError) {
          return res.status(transactionError.status).json({ success: false, message: transactionError.message });
        } else if (isTransactionConflict(transactionError)) {
          return res.status(409).json({ success: false, message: 'Inspection, Reservation or StorageUnit changed concurrently; reload and retry.' });
        } else {
          throw transactionError;
        }
      }
      if (!completedInspection) return res.status(503).json({ success: false, message: 'CHECK_IN outcome is uncertain; verify state before retrying.' });
      return res.json({ success: true, data: completedInspection });
    }

    const linkedReservation = await ReservationModel.findById(before.reservationId).select('serviceType').exec();
    if (linkedReservation?.serviceType === FacilityServiceType.MANAGED_INVENTORY) {
      return res.status(409).json({ success: false, message: 'Managed Inventory quota activation does not use Self Storage inspections.' });
    }
    const inspection = await InspectionModel.findOneAndUpdate(
      { _id: req.params.id, status: InspectionStatus.DRAFT } as any,
      { status: InspectionStatus.COMPLETED }, { new: true }
    );
    if (!inspection) return res.status(404).json({ success: false, message: 'Inspection not found or already completed' });

    // Nếu là CHECK_IN hoàn tất -> Update Reservation thành ACTIVE (giữ nguyên trạng thái vận hành AVAILABLE của StorageUnit để cho phép đặt lịch các ngày khác)
    if (inspection.type === InspectionType.CHECK_IN) {
      await ReservationModel.findByIdAndUpdate(inspection.reservationId, {
        status: ReservationStatus.ACTIVE,
        $push: {
          statusHistory: {
            status: ReservationStatus.ACTIVE,
            actorId: req.user!._id,
            reason: 'Hoàn tất bàn giao kho (CHECK_IN)'
          }
        }
      });
    } else if (inspection.type === InspectionType.CHECK_OUT) {
      // Nếu là CHECK_OUT hoàn tất -> Chuyển Reservation thành CHECKED_OUT và dọn dẹp StorageUnit
      await ReservationModel.findByIdAndUpdate(inspection.reservationId, {
        status: ReservationStatus.CHECKED_OUT,
        $push: {
          statusHistory: {
            status: ReservationStatus.CHECKED_OUT,
            actorId: req.user!._id,
            reason: 'Hoàn tất nghiệm thu trả kho (CHECK_OUT)'
          }
        }
      });

      // Nếu kho bị hỏng hoặc bẩn thì chuyển sang MAINTENANCE để dọn dẹp, ngược lại là AVAILABLE
      const nextUnitStatus = (inspection.condition === UnitCondition.DAMAGED || inspection.condition === UnitCondition.NEEDS_CLEANING)
        ? StorageUnitStatus.MAINTENANCE
        : StorageUnitStatus.AVAILABLE;

      await StorageUnitModel.findByIdAndUpdate(inspection.storageUnitId, {
        status: nextUnitStatus
      });
    }

    return res.json({ success: true, data: inspection });
  } catch (error: any) {
    return res.status(500).json({ success: false, message: error.message });
  }
};

