export const estimateRent = async (req: Request, res: Response) => {
  try {
    const { startDate, endDate, pricingPolicyId } = req.body;
    if (!startDate || !endDate || !pricingPolicyId) {
      return res.status(400).json({
        success: false,
        message: 'startDate, endDate và pricingPolicyId là các trường bắt buộc.'
      });
    }

    const result = await ReservationService.calculatePricing(
      pricingPolicyId,
      new Date(startDate),
      new Date(endDate)
    );

    return res.json({
      success: true,
      data: {
        estimatedRent: result.estimatedRent,
        depositAmount: result.depositAmount,
        taxAmount: 0,
        durationDays: result.durationDays,
        basePrice: result.basePrice
      }
    });
  } catch (error: any) {
    if (error instanceof ReservationError) {
      return res.status(error.code).json({ success: false, message: error.message });
    }
    return res.status(500).json({ success: false, message: error.message });
  }
};

/**
 * Khách hàng bắt đầu quy trình nộp cọc (Deposit)
 */

export const createSelfStorageCheckout = async (req: Request, res: Response) => {
  try {
    if (!req.body || typeof req.body !== 'object' || Array.isArray(req.body) ||
        Object.keys(req.body).some(key => key !== 'purpose')) {
      return res.status(400).json({ success: false, code: 'INVALID_PAYMENT_REQUEST', message: 'Only purpose is accepted in the request body' });
    }
    const result = await payosPaymentService.createCheckout(req.params.id, req.body.purpose,
      req.get('Idempotency-Key'), req.user!._id);
    const { httpStatus, outcome, ...data } = result;
    return res.status(httpStatus).json({ success: true, outcome, data });
  } catch (error) { return sendError(error, res); }
};

